create or replace function public.ver_equipo(p_jugador uuid) returns table (alias text, nombre text, rol_consultora text, es_yo boolean) language sql stable security definer set search_path = public as $$ select j.alias, j.nombre, j.rol_consultora, j.id = p_jugador from public.jugadores j join public.jugadores yo on yo.id = p_jugador where public.es_docente() and j.activo and yo.consultora is not null and j.consultora = yo.consultora and j.seccion_id is not distinct from yo.seccion_id order by j.nombre $$; create or replace function public.ver_eq_estado(p_jugador uuid) returns jsonb language sql stable security definer set search_path = public as $$ select case when not public.es_docente() then null else jsonb_build_object('evaluado', exists (select 1 from public.eq_perfil where jugador_id = p_jugador), 'strikes', (select count(*) from public.eq_reportes where reportado_id = p_jugador and estado = 'Validado'), 'motivos', coalesce((select jsonb_agg(jsonb_build_object('semana', semana, 'motivo', coalesce(nullif(nota_docente, ''), motivo)) order by creado) from public.eq_reportes where reportado_id = p_jugador and estado = 'Validado'), '[]'), 'penalidad', (select jsonb_build_object('penalidad', penalidad, 'nota', nota, 'estado', estado) from public.eq_penalidades where jugador_id = p_jugador), 'reportes_semana', (select count(*) from public.eq_reportes where reportante_id = p_jugador and creado > now() - interval '7 days')) end $$; create or replace function public.ver_equipo_semanas(p_jugador uuid) returns table (semana int, tema text, equipo numeric, clase numeric, grupal_equipo numeric, grupal_clase numeric) language sql stable security definer set search_path = public as $$ with yo as (select seccion_id, consultora from public.jugadores where id = p_jugador and public.es_docente()), d as (select d.semana, j.consultora, public.puntos(d) as p, coalesce(d.gr_comunicacion, 0) + coalesce(d.gr_tecnico, 0) + coalesce(d.gr_analisis, 0) + d.extra - d.falta as g, (d.gr_comunicacion is not null or d.gr_tecnico is not null or d.gr_analisis is not null) as gok from public.detalle d join public.jugadores j on j.id = d.jugador_id and j.activo join yo on j.seccion_id = yo.seccion_id) select d.semana, max(s.tema), round(avg(d.p) filter (where d.consultora = (select consultora from yo)), 2), round(avg(d.p), 2), round(avg(d.g) filter (where d.gok and d.consultora = (select consultora from yo)), 2), round(avg(d.g) filter (where d.gok), 2) from d left join public.semanas s on s.semana = d.semana where (select consultora from yo) is not null group by d.semana order by d.semana $$; revoke execute on function public.ver_equipo(uuid), public.ver_eq_estado(uuid), public.ver_equipo_semanas(uuid) from anon, public; grant execute on function public.ver_equipo(uuid), public.ver_eq_estado(uuid), public.ver_equipo_semanas(uuid) to authenticated; notify pgrst, 'reload schema';
